package com.chesspulseai.controller; import com.chesspulseai.dto.*; import com.chesspulseai.service.GameService; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/games") @Tag(name="Games") public class GameController {private final GameService service;public GameController(GameService s){service=s;}@PostMapping @ResponseStatus(HttpStatus.CREATED) public GameResponse create(@Valid @RequestBody CreateGameRequest r){return service.create(r);}@GetMapping public List<GameResponse> list(){return service.list();}@GetMapping("/{id}") public GameResponse get(@PathVariable UUID id){return service.get(id);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable UUID id){service.delete(id);}@PostMapping("/{id}/moves") @ResponseStatus(HttpStatus.CREATED) public MoveResponse add(@PathVariable UUID id,@Valid @RequestBody AddMoveRequest r){return service.add(id,r);}@GetMapping("/{id}/moves") public List<MoveResponse> moves(@PathVariable UUID id){return service.moveList(id);}@GetMapping("/{id}/analysis") public List<MoveResponse> analysis(@PathVariable UUID id){return service.moveList(id);}@GetMapping("/{id}/turning-points") public List<TurningPointResponse> points(@PathVariable UUID id){return service.turningPoints(id);}}
